const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const clean=s=>(s||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const year=v=>String(v||'').match(/\d{4}/)?.[0]||null;
async function openLibrary(q){const u=new URL('https://openlibrary.org/search.json');u.searchParams.set('q',q);u.searchParams.set('limit','6');u.searchParams.set('fields','key,title,author_name,first_publish_year,cover_i,subject');const r=await fetch(u,{headers:{'user-agent':'TasteConstellation/1.0'}});if(!r.ok)throw new Error(`Open Library ${r.status}`);const d=await r.json();return(d.docs||[]).map(x=>({id:`openlibrary:${x.key}`,externalId:x.key,title:x.title,originalTitle:null,creator:x.author_name?.slice(0,2).join(', ')||'작자 미상',year:x.first_publish_year||null,mediaType:'BOOK',posterUrl:x.cover_i?`https://covers.openlibrary.org/b/id/${x.cover_i}-M.jpg`:null,description:'Open Library 도서 정보',tags:(x.subject||[]).slice(0,4),source:'Open Library'}))}
async function aniList(q){const query=`query($search:String){Page(page:1,perPage:6){media(search:$search,type:ANIME,sort:SEARCH_MATCH){id title{userPreferred native} description(asHtml:false) startDate{year} coverImage{large} genres staff(perPage:1,sort:RELEVANCE){nodes{name{full}}}}}}`;const r=await fetch('https://graphql.anilist.co',{method:'POST',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify({query,variables:{search:q}})});if(!r.ok)throw new Error(`AniList ${r.status}`);const d=await r.json();return(d.data?.Page?.media||[]).map(x=>({id:`anilist:${x.id}`,externalId:String(x.id),title:x.title.userPreferred,originalTitle:x.title.native,creator:x.staff?.nodes?.[0]?.name?.full||'제작진 정보 없음',year:x.startDate?.year||null,mediaType:'ANIME',posterUrl:x.coverImage?.large||null,description:clean(x.description)||'AniList 애니메이션 정보',tags:(x.genres||[]).slice(0,4),source:'AniList'}))}
async function tmdb(q,env){if(!env.TMDB_READ_TOKEN)return[];const u=new URL('https://api.themoviedb.org/3/search/multi');u.searchParams.set('query',q);u.searchParams.set('language','ko-KR');u.searchParams.set('include_adult','false');const r=await fetch(u,{headers:{authorization:`Bearer ${env.TMDB_READ_TOKEN}`,accept:'application/json'}});if(!r.ok)throw new Error(`TMDB ${r.status}`);const d=await r.json();return(d.results||[]).filter(x=>x.media_type==='movie'||x.media_type==='tv').slice(0,6).map(x=>({id:`tmdb:${x.media_type}:${x.id}`,externalId:String(x.id),title:x.title||x.name,originalTitle:x.original_title||x.original_name,creator:x.media_type==='movie'?'영화':'TV 시리즈',year:year(x.release_date||x.first_air_date),mediaType:x.media_type==='movie'?'FILM':'TV',posterUrl:x.poster_path?`https://image.tmdb.org/t/p/w342${x.poster_path}`:null,description:x.overview||'TMDB 작품 정보',tags:[],source:'TMDB'}))}
async function googleBooks(q,env){if(!env.GOOGLE_BOOKS_API_KEY)return[];const u=new URL('https://www.googleapis.com/books/v1/volumes');u.searchParams.set('q',q);u.searchParams.set('maxResults','6');u.searchParams.set('key',env.GOOGLE_BOOKS_API_KEY);const r=await fetch(u);if(!r.ok)throw new Error(`Google Books ${r.status}`);const d=await r.json();return(d.items||[]).map(x=>{const v=x.volumeInfo||{};return{id:`googlebooks:${x.id}`,externalId:x.id,title:v.title,originalTitle:null,creator:(v.authors||[]).join(', ')||'작자 미상',year:year(v.publishedDate),mediaType:'BOOK',posterUrl:v.imageLinks?.thumbnail?.replace('http:','https:')||null,description:clean(v.description)||'Google Books 도서 정보',tags:(v.categories||[]).slice(0,4),source:'Google Books'}})}
function dedupe(items){const seen=new Set();return items.filter(x=>{const k=`${x.mediaType}:${x.title}`.toLowerCase().replace(/\s/g,'');if(seen.has(k))return false;seen.add(k);return true}).slice(0,18)}
async function search(request,env){const u=new URL(request.url),q=(u.searchParams.get('q')||'').trim();if(q.length<2)return json({items:[],sources:{},message:'두 글자 이상 입력해 주세요.'});const providers=[['TMDB',tmdb(q,env)],['Google Books',googleBooks(q,env)],['Open Library',openLibrary(q)],['AniList',aniList(q)]],settled=await Promise.allSettled(providers.map(x=>x[1]));let items=[];const sources={};settled.forEach((r,i)=>{const name=providers[i][0],configured=!(name==='TMDB'&&!env.TMDB_READ_TOKEN)&&!(name==='Google Books'&&!env.GOOGLE_BOOKS_API_KEY);sources[name]=!configured?'needs_key':r.status==='fulfilled'?'ok':'error';if(r.status==='fulfilled')items.push(...r.value)});return json({items:dedupe(items),sources,query:q})}
function currentUser(request){const id=request.headers.get('oai-authenticated-user-id');if(!id)return null;return{id,email:request.headers.get('oai-authenticated-user-email')||null}}
function dbReady(env){return Boolean(env.SUPABASE_URL&&env.SUPABASE_SERVICE_ROLE_KEY)}
async function supabase(env,path,{method='GET',body,prefer}={}){const r=await fetch(`${env.SUPABASE_URL}/rest/v1/${path}`,{method,headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,'content-type':'application/json',...(prefer?{prefer}:{})},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw new Error(`Supabase ${r.status}: ${(await r.text()).slice(0,240)}`);if(r.status===204)return null;const text=await r.text();return text?JSON.parse(text):null}
async function ensureProfile(env,user){await supabase(env,'profiles?on_conflict=user_id',{method:'POST',prefer:'resolution=merge-duplicates,return=minimal',body:{user_id:user.id,email:user.email}})}
function normalizeWork(w){return{id:String(w.id||'').slice(0,240),external_id:String(w.externalId||'').slice(0,240),title:String(w.title||'').slice(0,500),original_title:w.originalTitle?String(w.originalTitle).slice(0,500):null,creator:String(w.creator||'작자 미상').slice(0,500),release_year:w.year?Number(w.year)||null:null,media_type:String(w.mediaType||w.type||'OTHER').slice(0,32),poster_url:w.posterUrl?String(w.posterUrl).slice(0,1500):null,description:String(w.description||w.quote||'').slice(0,4000),tags:Array.isArray(w.tags)?w.tags.slice(0,12).map(x=>String(x).slice(0,100)):[],source:String(w.source||'Taste Constellation').slice(0,100)}}
function toClientWork(row){return{id:row.id,externalId:row.external_id,title:row.title,originalTitle:row.original_title,creator:row.creator,year:row.release_year,mediaType:row.media_type,posterUrl:row.poster_url,description:row.description,tags:row.tags||[],source:row.source}}
async function archive(request,env){if(!dbReady(env))return json({error:'Supabase가 아직 연결되지 않았습니다.'},503);const user=currentUser(request);if(!user)return json({error:'로그인이 필요합니다.'},401);await ensureProfile(env,user);if(request.method==='GET'){const rows=await supabase(env,`archive_items?user_id=eq.${encodeURIComponent(user.id)}&select=created_at,works(*)&order=created_at.desc`);return json({items:(rows||[]).filter(x=>x.works).map(x=>({...toClientWork(x.works),savedAt:x.created_at})),user:{email:user.email}})}if(request.method==='POST'){const payload=await request.json();const work=normalizeWork(payload.work||{});if(!work.id||!work.title)return json({error:'저장할 작품 정보가 올바르지 않습니다.'},400);await supabase(env,'works?on_conflict=id',{method:'POST',prefer:'resolution=merge-duplicates,return=minimal',body:work});await supabase(env,'archive_items?on_conflict=user_id,work_id',{method:'POST',prefer:'resolution=ignore-duplicates,return=minimal',body:{user_id:user.id,work_id:work.id}});return json({saved:true,work:toClientWork(work)},201)}return json({error:'지원하지 않는 요청입니다.'},405)}
async function removeArchive(request,env,id){if(!dbReady(env))return json({error:'Supabase가 아직 연결되지 않았습니다.'},503);const user=currentUser(request);if(!user)return json({error:'로그인이 필요합니다.'},401);await supabase(env,`archive_items?user_id=eq.${encodeURIComponent(user.id)}&work_id=eq.${encodeURIComponent(id)}`,{method:'DELETE',prefer:'return=minimal'});return json({saved:false})}
export default{async fetch(request,env){try{const u=new URL(request.url);if(u.pathname==='/api/search')return search(request,env);if(u.pathname==='/api/archive')return archive(request,env);if(u.pathname.startsWith('/api/archive/')&&request.method==='DELETE')return removeArchive(request,env,decodeURIComponent(u.pathname.slice(13)));if(u.pathname==='/api/health')return json({ok:true,sources:{tmdb:!!env.TMDB_READ_TOKEN,googleBooks:!!env.GOOGLE_BOOKS_API_KEY,openLibrary:true,aniList:true,supabase:dbReady(env)}});if(env.ASSETS)return env.ASSETS.fetch(request);return new Response('Not found',{status:404})}catch(error){console.error(error);return json({error:'요청을 처리하지 못했습니다. 잠시 후 다시 시도해 주세요.'},500)}}};
